14	export interface AgentProtocol extends Trajectory {
15	  /**
16	   * Send data to the agent. Promise resolves when action is acknowledged.
17	   * Returns the agent-activity `streamId` affected by the send. This may be a
18	   * new stream if idle, an existing stream, or null if the send was
19	   * acknowledged without starting agent activity. Emitted events should still
20	   * remain correlated to a stream via their `streamId`.
21	   *
22	   * When a new stream is created by a send, the streamId MUST be returned
23	   * before the `agent_start` event is emitted for the stream.
24	   */
25	  send(payload: AgentSend): Promise<{ streamId: string | null }>;
26	
27	  /**
28	   * Subscribes the provided callback to all future events emitted by this
29	   * session. Returns an unsubscribe function.
30	   *
31	   * @param callback The callback function to listen to events.
32	   */
33	  subscribe(callback: (event: AgentEvent) => void): Unsubscribe;
34	
35	  /**
36	   * Aborts an active stream of agent activity.
37	   */
38	  abort(): Promise<void>;
39	
40	  /**
41	   * AgentProtocol implements the Trajectory interface and can retrieve existing events.
42	   */
43	  readonly events: readonly AgentEvent[];
44	}
