164	/**
165	 * Extracts a target URL for auth providers from a RemoteAgentDefinition.
166	 * For URL-based agents, returns the agentCardUrl.
167	 * For JSON-based agents, attempts to parse the URL from the inline card JSON.
168	 * Returns undefined if no URL can be determined.
169	 */
170	export function getRemoteAgentTargetUrl(
171	  def: RemoteAgentRef,
172	): string | undefined {
173	  if (def.agentCardUrl) {
174	    return def.agentCardUrl;
175	  }
176	  if (def.agentCardJson) {
177	    try {
178	      const parsed: unknown = JSON.parse(def.agentCardJson);
179	      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
180	      const card = parsed as AgentCard;
181	      if (card.url) {
182	        return card.url;
183	      }
184	    } catch {
185	      // JSON parse will fail properly later in loadAgent
186	    }
187	  }
188	  return undefined;
189	}
