40	/**
41	 * Represents a validated, executable instance of a subagent tool.
42	 *
43	 * This class orchestrates the execution of a defined agent by:
44	 * 1. Initializing the {@link LocalAgentExecutor}.
45	 * 2. Running the agent's execution loop.
46	 * 3. Bridging the agent's streaming activity (e.g., thoughts) to the tool's
47	 * live output stream.
48	 * 4. Formatting the final result into a {@link ToolResult}.
49	 */
50	export class LocalSubagentInvocation extends BaseToolInvocation<
51	  AgentInputs,
52	  ToolResult
53	> {
54	  /**
55	   * @param definition The definition object that configures the agent.
56	   * @param context The agent loop context.
57	   * @param params The validated input parameters for the agent.
58	   * @param messageBus Message bus for policy enforcement.
59	   */
60	  constructor(
61	    private readonly definition: LocalAgentDefinition,
62	    private readonly context: AgentLoopContext,
63	    params: AgentInputs,
64	    messageBus: MessageBus,
65	    _toolName?: string,
66	    _toolDisplayName?: string,
67	  ) {
68	    super(
69	      params,
70	      messageBus,
71	      _toolName ?? definition.name,
72	      _toolDisplayName ?? definition.displayName,
73	    );
74	  }
75	
76	  /**
77	   * Returns a concise, human-readable description of the invocation.
78	   * Used for logging and display purposes.
79	   */
80	  getDescription(): string {
81	    const inputSummary = Object.entries(this.params)
82	      .map(
83	        ([key, value]) =>
84	          `${key}: ${String(value).slice(0, INPUT_PREVIEW_MAX_LENGTH)}`,
85	      )
86	      .join(', ');
87	
88	    const description = `Running subagent '${this.definition.name}' with inputs: { ${inputSummary} }`;
89	    return description.slice(0, DESCRIPTION_MAX_LENGTH);
90	  }
