7	import type { Part } from '@google/genai';
8	import type { ContentPart } from './types.js';
9	import { debugLogger } from '../utils/debugLogger.js';
10	
11	/**
12	 * Converts Gemini API Part objects to framework-agnostic ContentPart objects.
13	 * Handles text, thought, inlineData, fileData parts and serializes unknown
14	 * part types to text to avoid silent data loss.
15	 */
16	export function geminiPartsToContentParts(parts: Part[]): ContentPart[] {
17	  const result: ContentPart[] = [];
18	  for (const part of parts) {
19	    if ('text' in part && part.text !== undefined) {
20	      if ('thought' in part && part.thought) {
21	        result.push({
22	          type: 'thought',
23	          thought: part.text,
24	          ...(part.thoughtSignature
25	            ? { thoughtSignature: part.thoughtSignature }
26	            : {}),
27	        });
28	      } else {
29	        result.push({ type: 'text', text: part.text });
30	      }
31	    } else if ('inlineData' in part && part.inlineData) {
32	      result.push({
33	        type: 'media',
34	        data: part.inlineData.data,
35	        mimeType: part.inlineData.mimeType,
36	      });
37	    } else if ('fileData' in part && part.fileData) {
38	      result.push({
39	        type: 'media',
40	        uri: part.fileData.fileUri,
41	        mimeType: part.fileData.mimeType,
42	      });
43	    } else if ('functionCall' in part && part.functionCall) {
44	      continue; // Skip function calls, they are emitted as distinct tool_request events
45	    } else if ('functionResponse' in part && part.functionResponse) {
46	      continue; // Skip function responses, they are tied to tool_response events
47	    } else {
48	      // Fallback: serialize any unrecognized part type to text
49	      result.push({
50	        type: 'text',
51	        text: JSON.stringify(part),
52	        _meta: { partType: 'unknown' },
53	      });
54	    }
55	  }
56	  return result;
57	}
58	
59	/**
60	 * Converts framework-agnostic ContentPart objects to Gemini API Part objects.
61	 */
62	export function contentPartsToGeminiParts(content: ContentPart[]): Part[] {
63	  const result: Part[] = [];
64	  for (const part of content) {
65	    switch (part.type) {
66	      case 'text':
67	        result.push({ text: part.text });
68	        break;
69	      case 'thought':
70	        result.push({
71	          text: part.thought,
72	          thought: true,
73	          ...(part.thoughtSignature
74	            ? { thoughtSignature: part.thoughtSignature }
75	            : {}),
76	        });
77	        break;
78	      case 'media':
79	        if (part.data) {
80	          result.push({
81	            inlineData: {
82	              data: part.data,
83	              mimeType: part.mimeType ?? 'application/octet-stream',
84	            },
85	          });
86	        } else if (part.uri) {
87	          result.push({
88	            fileData: { fileUri: part.uri, mimeType: part.mimeType },
89	          });
90	        }
91	        break;
92	      case 'reference':
93	        // References are converted to text for the model
94	        result.push({ text: part.text });
95	        break;
96	      default:
97	        debugLogger.warn(
98	          `Unhandled ContentPart type: ${JSON.stringify(part)} fallback to serialization`,
99	        );
100	        // Serialize unknown ContentPart variants instead of dropping them
101	        result.push({ text: JSON.stringify(part) });
102	        break;
103	    }
104	  }
105	  return result;
106	}
