108	/**
109	 * Builds the data record for a tool_response AgentEvent, preserving
110	 * all available metadata from the ToolCallResponseInfo.
111	 */
112	export function buildToolResponseData(response: {
113	  data?: Record<string, unknown>;
114	  errorType?: string;
115	  outputFile?: string;
116	  contentLength?: number;
117	}): Record<string, unknown> | undefined {
118	  const parts: Record<string, unknown> = {};
119	  if (response.data) Object.assign(parts, response.data);
120	  if (response.errorType) parts['errorType'] = response.errorType;
121	  if (response.outputFile) parts['outputFile'] = response.outputFile;
122	  if (response.contentLength !== undefined)
123	    parts['contentLength'] = response.contentLength;
124	  return Object.keys(parts).length > 0 ? parts : undefined;
125	}
