vi.mock('../agents/local-executor.js', () => ({
  LocalAgentExecutor: { create: vi.fn() },
}));

const def = { name: 'a', displayName: 'A', kind: 'local' } as never;
const ctx = {} as never;
const bus = {} as never;

function msg(text: string): AgentSend {
  return { message: { content: [{ type: 'text', text }] } } as AgentSend;
}

function mockExecutor(
  run: (inputs: unknown, signal: AbortSignal) => Promise<unknown>,
  emit?: (cb: (a: SubagentActivityEvent) => void) => void,
) {
  vi.mocked(LocalAgentExecutor.create).mockImplementation(
    async (_d, _c, onActivity) => {
      const exec = {
        agentId: 'x',
        run: (inputs: unknown, signal: AbortSignal) => {
          emit?.(onActivity as (a: SubagentActivityEvent) => void);
          return run(inputs, signal);
        },
      };
      return exec as never;
    },
  );
}

describe('LocalSubagentSession smoke', () => {
  beforeEach(() => vi.clearAllMocks());

  it('update buffers config and returns null streamId', async () => {
    mockExecutor(async () => ({
      result: 'ok',
      terminate_reason: AgentTerminateMode.GOAL,
    }));
    const s = new LocalSubagentSession(def, ctx, bus);
    const r = await s.send({ update: { config: { foo: 1 } } } as AgentSend);
    expect(r.streamId).toBeNull();

    let capturedInputs: unknown;
    mockExecutor(async (inputs) => {
      capturedInputs = inputs;
      return { result: 'ok', terminate_reason: AgentTerminateMode.GOAL };
    });
    const r2 = await s.send(msg('hello'));
    expect(typeof r2.streamId).toBe('string');
    const out = await s.getResult();
    expect(out.result).toBe('ok');
    expect(capturedInputs).toEqual({ foo: 1, query: 'hello' });
  });

  it('omits query when message empty and clears buffer', async () => {
    let capturedInputs: unknown;
    mockExecutor(async (inputs) => {
      capturedInputs = inputs;
      return { result: 'ok', terminate_reason: AgentTerminateMode.GOAL };
    });
    const s = new LocalSubagentSession(def, ctx, bus);
    await s.send({ update: { config: { a: 1 } } } as AgentSend);
    await s.send(msg(''));
    await s.getResult();
    expect(capturedInputs).toEqual({ a: 1 });
    // buffer cleared after send
    let second: unknown;
    mockExecutor(async (inputs) => {
      second = inputs;
      return { result: 'ok2', terminate_reason: AgentTerminateMode.GOAL };
    });
    await s.send(msg('again'));
    await s.getResult();
    expect(second).toEqual({ query: 'again' });
  });

  it('emits agent_start first and agent_end last, translates activity', async () => {
    mockExecutor(
      async () => ({ result: 'r', terminate_reason: AgentTerminateMode.GOAL }),
      (cb) => {
        cb({
          isSubagentActivityEvent: true,
          agentName: 'a',
          type: 'THOUGHT_CHUNK',
          data: { text: 'thinking' },
        });
        cb({
          isSubagentActivityEvent: true,
          agentName: 'a',
          type: 'TOOL_CALL_START',
          data: { name: 'ls', callId: 'c1', args: { p: '.' } },
        });
        cb({
          isSubagentActivityEvent: true,
          agentName: 'a',
          type: 'TOOL_CALL_END',
          data: { name: 'ls', id: 'c1', output: 'files' },
        });
      },
    );
    const s = new LocalSubagentSession(def, ctx, bus);
    const events: AgentEvent[] = [];
    s.subscribe((e) => events.push(e));
    await s.send(msg('go'));
    await s.getResult();
    const types = events.map((e) => e.type);
    expect(types[0]).toBe('agent_start');
    expect(types[types.length - 1]).toBe('agent_end');
    expect(types).toContain('message');
    expect(types).toContain('tool_request');
    expect(types).toContain('tool_response');
    // all same streamId
    const ids = new Set(events.map((e) => e.streamId));
    expect(ids.size).toBe(1);
    const end = events.find((e) => e.type === 'agent_end') as AgentEvent<'agent_end'>;
    expect(end.reason).toBe('completed');
  });

  it('rejects concurrent message sends while active', async () => {
    let resolveRun!: (v: unknown) => void;
    mockExecutor(() => new Promise((res) => (resolveRun = res)));
    const s = new LocalSubagentSession(def, ctx, bus);
    await s.send(msg('go'));
    await new Promise((r) => setTimeout(r, 5));
    await expect(s.send(msg('again'))).rejects.toThrow(
      'cannot be called while a stream is active',
    );
    resolveRun({ result: 'r', terminate_reason: AgentTerminateMode.GOAL });
    await s.getResult();
  });

  it('getResult rejects before any send', async () => {
    mockExecutor(async () => ({
      result: 'r',
      terminate_reason: AgentTerminateMode.GOAL,
    }));
    const s = new LocalSubagentSession(def, ctx, bus);
    await expect(s.getResult()).rejects.toThrow('No active or completed stream');
  });

  it('abort resolves getResult with ABORTED and emits aborted end', async () => {
    let resolveRun!: (v: unknown) => void;
    mockExecutor(() => new Promise((res) => (resolveRun = res)));
    const s = new LocalSubagentSession(def, ctx, bus);
    const events: AgentEvent[] = [];
    s.subscribe((e) => events.push(e));
    await s.send(msg('go'));
    await new Promise((r) => setTimeout(r, 5));
    await s.abort();
    const out = await s.getResult();
    expect(out).toEqual({ result: '', terminate_reason: AgentTerminateMode.ABORTED });
    const end = events.find((e) => e.type === 'agent_end') as AgentEvent<'agent_end'>;
    expect(end.reason).toBe('aborted');
    resolveRun({ result: 'late', terminate_reason: AgentTerminateMode.ABORTED });
    await new Promise((r) => setTimeout(r, 5));
    // only one agent_end
    expect(events.filter((e) => e.type === 'agent_end').length).toBe(1);
  });

  it('rejects getResult with executor error on failure', async () => {
    mockExecutor(async () => {
      throw new Error('boom');
    });
    const s = new LocalSubagentSession(def, ctx, bus);
    const events: AgentEvent[] = [];
    s.subscribe((e) => events.push(e));
    await s.send(msg('go'));
    await expect(s.getResult()).rejects.toThrow('boom');
    const types = events.map((e) => e.type);
    expect(types).toContain('error');
    expect(types[types.length - 1]).toBe('agent_end');
  });

  it('sequential streams have distinct ids', async () => {
    mockExecutor(async () => ({
      result: 'r',
      terminate_reason: AgentTerminateMode.GOAL,
    }));
    const s = new LocalSubagentSession(def, ctx, bus);
    const r1 = await s.send(msg('a'));
    await s.getResult();
    const r2 = await s.send(msg('b'));
    await s.getResult();
    expect(r1.streamId).not.toBe(r2.streamId);
  });
});
